 1: - name: Determine if systemd-boot is used
 2:   ansible.builtin.stat:
 3:     path: /etc/kernel/cmdline
 4:   register: proxmox_etc_kernel_cmdline
 5: 
 6: - name: Configure systemd-boot kernel commandline
 7:   when: proxmox_etc_kernel_cmdline.stat.exists
 8:   block:
 9:     - name: Collect kernel parameters
10:       ansible.builtin.set_fact:
11:         proxmox_kernel_cmdline: >-
12:           {{
13:             proxmox_kernel_parameters_yaml |
14:             ansible.builtin.from_yaml |
15:             default([], true) |
16:             unique |
17:             join(' ')
18:           }}
19:       vars:
20:         proxmox_kernel_parameters_yaml: |
21:           {% for k in proxmox_kernel_cmdline | default([]) %}
22:           - {{ k }}
23:           {% endfor %}
24:           {% if 'GenuineIntel' in ansible_facts.processor %}
25:           - intel_iommu=on
26:           {% endif %}
27:           {% if pve_iommu_passthrough_mode | ansible.builtin.bool %}
28:           - iommu=pt
29:           {% endif %}
30:           {% if pve_mediated_devices_enabled | ansible.builtin.bool %}
31:           - i915.enable_gvt=1
32:           - i915.enable_guc=0
33:           {% endif %}
34:           {% if pve_pci_device_ids | length > 0 %}
35:           - vfio-pci.ids={{ pve_pci_device_ids | map(attribute='id') | join(',') }}
36:           {% endif %}
37: 
38:     - name: Set kernel parameters
39:       ansible.builtin.copy:
40:         content: >
41:           {{ item }}
42:         dest: "{{ proxmox_etc_kernel_cmdline.stat.path }}"
43:         backup: true
44:         owner: 0
45:         group: 0
46:         mode: "644"
47:       loop:
48:         - "{{ proxmox_kernel_cmdline }}"
49:       notify: Run proxmox-boot-tool refresh

 1: - name: Cluster {{ cluster_id }} - Create directories
 2:   file:
 3:     path: "{{ item }}"
 4:     state: directory
 5:     mode: 0755 # For some reason, item.mode converts 0755 into 493 ... weird
 6:   loop:
 7:     - clusters/{{ cluster_id }}
 8: 
 9: - name: Cluster {{ cluster_id }} - Create openshift-install configuration
10:   template:
11:     src: "{{ item.src }}"
12:     dest: "{{ item.dest }}"
13:   vars:
14:     ssh_pub_key: "{{ ssh_pub_key_task.stdout }}"
15:     pull_secret: "{{ lookup('file', './files/pull_secret.txt', errors='ignore') }}"
16:   with_items:
17:     - {
18:         src: templates/install-config.yaml.j2,
19:         dest: "clusters/{{ cluster_id }}/install-config.yaml",
20:       }
21:     - {
22:         src: templates/agent-config.yaml.j2,
23:         dest: "clusters/{{ cluster_id }}/agent-config.yaml",
24:       }
25:   register: okd_installer_config_files
26: 
27: # Let's create the proper OKD installation files (ignition, manifests, ...)
28: - name: Cluster {{ cluster_id }} - Run openshift-installer
29:   when: okd_installer_config_files.changed
30:   shell: |
31:     cd clusters/{{ cluster_id }}
32:     rm -rf install-dir
33:     mkdir install-dir
34:     cp install-config.yaml agent-config.yaml install-dir/
35:     {% if ipxe.enabled %}
36:       {% set cmd = "pxe-files" %}
37:     {% else %}
38:       {% set cmd = "image" %}
39:     {% endif %}
40:     openshift-install agent create {{ cmd }} --dir=install-dir
41:   environment:
42:     PATH: "/usr/local/bin:/usr/bin:/bin"
43:   register: installer_task
44: 
45: # Make these files available on the Web server
46: - name: Cluster {{ cluster_id }} - Copy boot-artifacts to www directory
47:   when: installer_task.changed
48:   become: true
49:   shell: |
50:     rm -rf /var/www/html/{{ cluster_id }}
51:     mkdir /var/www/html/{{ cluster_id }}
52:     {% if ipxe.enabled %}
53:     cp -R clusters/{{ cluster_id }}/install-dir/boot-artifacts/* /var/www/html/{{ cluster_id }}
54:     {% else %}
55:     cp clusters/{{ cluster_id }}/install-dir/agent.x86_64.iso /var/www/html/{{ cluster_id }}/
56:     {% endif %}
57:     chmod -R 755 /var/www/html/{{ cluster_id }}

 1: ---
 2: - name: bootstrap gateway
 3:   hosts: all
 4:   gather_facts: true
 5:   become: true
 6:   any_errors_fatal: true
 7:   roles:
 8:   - { role: os_base }
 9:   - { role: ansible-pull }
10:   - { role: tailscale }
11:   - { role: caddy }

 1: ---
 2: - name: Look up existing Route host
 3:   kubernetes.core.k8s_info:
 4:     api_version: '{{ route_api_version }}'
 5:     kind: Route
 6:     namespace: '{{ ansible_operator_meta.namespace }}'
 7:     name: '{{ ansible_operator_meta.name }}'
 8:   register: _existing_route
 9:   when: ingress_type | lower == 'route'
10: 
11: - name: Set CSRF trusted origins
12:   ansible.builtin.set_fact:
13:     _csrf_trusted_origins: >-
14:       {%- set origins = [] -%}
15:       {%- if ingress_type | lower == 'route' -%}
16:         {%- if route_host | length -%}
17:           {%- set _ = origins.append('https://' + route_host) -%}
18:         {%- elif _existing_route.resources | default([]) | length > 0
19:                 and _existing_route.resources[0].status is defined
20:                 and _existing_route.resources[0].status.ingress is defined
21:                 and _existing_route.resources[0].status.ingress | length > 0 -%}
22:           {%- set _ = origins.append('https://' + _existing_route.resources[0].status.ingress[0].host) -%}
23:         {%- endif -%}
24:       {%- elif ingress_type | lower == 'ingress' and hostname | length -%}
25:         {%- set scheme = 'https' if ingress_tls_secret | length else 'http' -%}
26:         {%- set _ = origins.append(scheme + '://' + hostname) -%}
27:       {%- endif -%}
28:       {%- if auth_config is defined
29:               and auth_config.resources | default([]) | length > 0
30:               and auth_config.resources[0].data.auth_api_url is defined -%}
31:         {%- set gateway_url = auth_config.resources[0].data.auth_api_url | b64decode -%}
32:         {%- set gw_scheme = gateway_url | urlsplit('scheme') -%}
33:         {%- set gw_netloc = gateway_url | urlsplit('netloc') -%}
34:         {%- if gw_scheme and gw_netloc -%}
35:           {%- set gw_origin = gw_scheme + '://' + gw_netloc -%}
36:           {%- if gw_origin not in origins -%}
37:             {%- set _ = origins.append(gw_origin) -%}
38:           {%- endif -%}
39:         {%- endif -%}
40:       {%- endif -%}
41:       {%- if _aap_gateway_url is defined and _aap_gateway_url | length -%}
42:         {%- set gw2_scheme = _aap_gateway_url | urlsplit('scheme') -%}
43:         {%- set gw2_netloc = _aap_gateway_url | urlsplit('netloc') -%}
44:         {%- if gw2_scheme and gw2_netloc -%}
45:           {%- set gw2_origin = gw2_scheme + '://' + gw2_netloc -%}
46:           {%- if gw2_origin not in origins -%}
47:             {%- set _ = origins.append(gw2_origin) -%}
48:           {%- endif -%}
49:         {%- endif -%}
50:       {%- endif -%}
51:       {{- origins | join(',') -}}

  1: ---
  2: - name: Print Bloom Configuration Values
  3:   hosts: localhost
  4:   gather_facts: no
  5: 
  6:   tasks:
  7:     - name: Print configuration header
  8:       debug:
  9:         msg: "=== Bloom Configuration Values ==="
 10: 
 11:     - name: Print Basic Configuration
 12:       debug:
 13:         msg: |
 14:           📋 Basic Configuration:
 15:             FIRST_NODE: {{ FIRST_NODE | default('NOT SET') }}
 16:             GPU_NODE: {{ GPU_NODE | default('NOT SET') }}
 17:             DOMAIN: {{ DOMAIN | default('NOT SET') }}
 18:             CLUSTER_SIZE: {{ CLUSTER_SIZE | default('NOT SET') }}
 19:             SERVER_IP: {{ SERVER_IP | default('NOT SET') }}
 20: 
 21:     - name: Print Cluster Size Optimizations
 22:       debug:
 23:         msg: |
 24:           📏 Cluster Size Impact ({{ CLUSTER_SIZE | default('NOT SET') }}):
 25:           {% if CLUSTER_SIZE == 'small' %}
 26:             🔧 Cilium Operator Replicas: 1 (HelmChartConfig at bootstrap)
 27:             💾 Storage Provisioner: local-path-provisioner (high-performance local storage)
 28:             🎯 Target Scale: Up to 3 nodes, development/testing workloads
 29:             📝 Resource Profile: Minimal overhead, reduced HA for cost efficiency
 30:             📊 Hubble Observability: Disabled (saves resources)
 31:           {% elif CLUSTER_SIZE == 'medium' %}
 32:             🔧 Cilium Operator Replicas: 1 (HelmChartConfig at bootstrap)
 33:             💾 Storage Provisioner: local-path-provisioner (high-performance local storage)
 34:             🎯 Target Scale: 1-3 nodes, development/testing workloads
 35:             📝 Resource Profile: Minimal overhead, reduced HA for cost efficiency
 36:             📊 Hubble Observability: Disabled (saves resources)
 37:           {% elif CLUSTER_SIZE == 'large' %}
 38:             🔧 Cilium Operator Replicas: 2 (RKE2 chart default)
 39:             💾 Storage Provisioner: Longhorn (distributed storage with replication)
 40:             🎯 Target Scale: 10+ nodes, enterprise workloads
 41:             📝 Resource Profile: High availability and performance
 42:             📊 Hubble Observability: Disabled (security and performance)
 43:           {% else %}
 44:             🔧 Cilium Operator Replicas: 2 (default; use small/medium for 1 at bootstrap)
 45:             💾 Storage Provisioner: Longhorn (default distributed storage)
 46:             📝 Note: Set CLUSTER_SIZE (small/medium/large) to optimize deployment
 47:           {% endif %}
