 8: - name: (Deprecation) Catch and report renamed Buscarron settings
 9:   ansible.builtin.fail:
10:     msg: >-
11:       Your configuration contains a variable, which now has a different name.
12:       Please rename the variable (`{{ item.old }}` -> `{{ item.new }}`) on your configuration file (vars.yml).
13:   when: "lookup('ansible.builtin.varnames', ('^' + item.old + '$'), wantlist=True) | length > 0"
14:   with_items:
15:     - {'old': 'matrix_bot_buscarron_noencryption', 'new': '<removed>'}
16:     - {'old': 'matrix_bot_buscarron_spam_hosts', 'new': '<superseded by matrix_bot_buscarron_spamlist>'}
17:     - {'old': 'matrix_bot_buscarron_spam_emails', 'new': '<superseded by matrix_bot_buscarron_spamlist>'}
18:     - {'old': 'matrix_bot_buscarron_spam_localparts', 'new': '<superseded by matrix_bot_buscarron_spamlist>'}
19:     - {'old': 'matrix_bot_buscarron_container_image_name_prefix', 'new': 'matrix_bot_buscarron_container_image_registry_prefix'}
20:     - {'old': 'matrix_bot_buscarron_docker_image', 'new': 'matrix_bot_buscarron_container_image'}
21:     - {'old': 'matrix_bot_buscarron_docker_image_force_pull', 'new': 'matrix_bot_buscarron_container_image_force_pull'}
22:     - {'old': 'matrix_bot_buscarron_container_image_force_pull', 'new': '<removed> (the new community.docker.docker_image_pull module handles this natively)'}
23:     - {'old': 'matrix_bot_buscarron_docker_image_registry_prefix', 'new': 'matrix_bot_buscarron_container_image_registry_prefix'}
24:     - {'old': 'matrix_bot_buscarron_docker_image_registry_prefix_upstream', 'new': 'matrix_bot_buscarron_container_image_registry_prefix_upstream'}
25:     - {'old': 'matrix_bot_buscarron_docker_image_registry_prefix_upstream_default', 'new': 'matrix_bot_buscarron_container_image_registry_prefix_upstream_default'}
26:     - {'old': 'matrix_bot_buscarron_docker_repo', 'new': 'matrix_bot_buscarron_container_repo'}
27:     - {'old': 'matrix_bot_buscarron_docker_repo_version', 'new': 'matrix_bot_buscarron_container_repo_version'}
28:     - {'old': 'matrix_bot_buscarron_docker_src_files_path', 'new': 'matrix_bot_buscarron_container_src_files_path'}
29: 
30: - name: Fail if required Buscarron settings not defined
31:   ansible.builtin.fail:
32:     msg: >-
33:       You need to define a required configuration setting (`{{ item.name }}`).
34:   when: "item.when | bool and lookup('vars', item.name, default='') | string | length == 0"
35:   with_items:
36:     - {'name': 'matrix_bot_buscarron_password', when: true}
37:     - {'name': 'matrix_bot_buscarron_hostname', when: true}
38:     - {'name': 'matrix_bot_buscarron_database_hostname', when: "{{ matrix_bot_buscarron_database_engine == 'postgres' }}"}
39:     - {'name': 'matrix_bot_buscarron_homeserver', when: true}

1: - hosts: all
2:   roles:
3:     - { role: utils/auto-backup-services }
